# shellcheck shell=bash

installKernelModules() {
  local -a dirs=()
  concatTo dirs kernelModuleDirs
  if [ ${#dirs[@]} -eq 0 ]; then
    dirs=(.)
  fi

  # One shell-quoted element per line, generated by makeSetupHook from
  # kernelModuleMakeFlags. The single quotes keep make syntax such as
  # kbuild's `$(space)` unexpanded until make expands it.

  # shellcheck disable=SC2154
  local -a flags=(
    @moduleInstallFlags@
    "INSTALL_MOD_PATH=$out"
    "INSTALL_MOD_DIR=${kernelModuleInstallDir:-updates}"
    "DEPMOD=true"
  )

  local dir modDir
  for dir in "${dirs[@]}"; do
    if [ ! -d "$dir" ]; then
      if [ "${kernelModuleSkipMissingDirs-}" != 1 ]; then
        echo "installKernelModules: '$dir' does not exist (set kernelModuleSkipMissingDirs=1 to skip missing directories)" >&2
        return 1
      fi
      echo "installKernelModules: skipping '$dir': no such directory" >&2
      continue
    fi
    if [ "$dir" = "." ]; then
      modDir=$PWD
    else
      modDir=$PWD/$dir
    fi
    echo "installKernelModules: installing modules from $modDir"
    make -C '@kernelBuildDir@' "M=$modDir" "${flags[@]}" modules_install
  done
}

installKernelModulesPhase() {
  echo "Executing installKernelModulesPhase"

  runHook preInstall
  installKernelModules
  runHook postInstall
}

if [ -z "${dontInstallKernelModules-}" ] && [ -z "${installPhase-}" ]; then
    installPhase=installKernelModulesPhase
fi
